#include <vector>
#include <algorithm>

class Solution {
public:
    std::vector<bool> kidsWithCandies(std::vector<int>& candies, int extraCandies) {
        int maxC = *std::max_element(candies.begin(), candies.end());
        std::vector<bool> res;
        for (int c : candies) {
            res.push_back(c + extraCandies >= maxC);
        }
        return res;
    }
};

import java.util.*;

class Solution {
    public List<Boolean> kidsWithCandies(int[] candies, int extraCandies) {
        int maxC = 0;
        for (int c : candies) maxC = Math.max(maxC, c);
        List<Boolean> res = new ArrayList<>();
        for (int c : candies) {
            res.add(c + extraCandies >= maxC);
        }
        return res;
    }
}

var kidsWithCandies = function(candies, extraCandies) {
    const maxC = Math.max(...candies);
    return candies.map(c => c + extraCandies >= maxC);
};
